/* spawns two bursts of particles around a point */
void spawn_collision_particle_bursts(void) {
    float v[4];
    float p[4];
    float a, b;
    int i;
    FastVecSub(v, camera_pos, novalis_coll_hit_point);
    a = -fast_atan2(vec_length_xy(v), v[2]);
    fast_atan2(v[0], v[1]);
    for (i = 19; i >= 0; i--) {
        float x, y;
        x = FastAddRots(randf_sym(0.0f, 3.1415927f), a);
        y = FastAddRots(randf_sym(0.0f, 3.1415927f), a);
        BuildSphericalOffset(v, 0.2f, y, x);
        FastVecScale(p, v, random_float_between(1.0f, 3.0f));
        FastVecAdd(p, p, novalis_coll_hit_point);
        spawn_two_point_effect_particle((char *)p, (char *)v);
    }
    for (i = 9; i >= 0; i--) {
        float x, y;
        p[0] = novalis_coll_hit[8] + randf_sym(0.0f, 0.1f);
        p[1] = novalis_coll_hit[9] + randf_sym(0.0f, 0.1f);
        p[2] = novalis_coll_hit[10] + randf_sym(0.0f, 0.1f);
        x = FastAddRots(randf_sym(0.0f, 3.1415927f), a);
        y = FastAddRots(randf_sym(0.0f, 3.1415927f), a);
        BuildSphericalOffset(v, 0.05f, y, x);
        PartType21Spawn(p, v, 0x4F007FFF, 0x1FFFFFFF, rand_range(scale_ticks(10), scale_ticks(20)), 1, 20000.0f);
    }
}
