        hp = GetFlaggedPvarWord_t(t);
        if (!(*(unsigned short *)(t + 0x34) & 0x1000) || t == 0 || *(char **)(t + 0x24) == 0) continue;
        cls = *(short *)(*(char **)(t + 0x24) + 0x46);
